const items = $input.all();
const results = [];
const promoKeywords = ['unsubscribe', 'opt out', 'email preferences', 'manage subscriptions',
  'promotional', 'newsletter', 'weekly digest', 'special offer', 'limited time',
  'discount', 'sale', 'deal', 'coupon', 'free trial'];

for (const item of items) {
  const subject = (item.json.subject || '').toLowerCase();
  const body = (item.json.snippet || item.json.textPlain || '').toLowerCase();
  const from = item.json.from || '';
  const combined = subject + ' ' + body;

  let promoScore = 0;
  const matchedKeywords = [];

  for (const keyword of promoKeywords) {
    if (combined.includes(keyword)) {
      promoScore++;
      matchedKeywords.push(keyword);
    }
  }

  if (promoScore >= 2) {
    results.push({
      json: {
        sender: from,
        subject: item.json.subject,
        promoScore: promoScore,
        matchedKeywords: matchedKeywords.join(', '),
        recommendation: promoScore >= 4 ? 'Strongly recommend unsubscribe' : 'Consider unsubscribe',
        detectedAt: new Date().toISOString()
      }
    });
  }
}

// Deduplicate by sender
const seen = new Set();
const unique = results.filter(r => {
  const key = r.json.sender;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return unique;
